func testLLMMarketSnapshotToManyAddOpSnapshotLLMDecisionRuns(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a LLMMarketSnapshot
	var b, c, d, e LLMDecisionRun

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, llmMarketSnapshotDBTypes, false, strmangle.SetComplement(llmMarketSnapshotPrimaryKeyColumns, llmMarketSnapshotColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*LLMDecisionRun{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, llmDecisionRunDBTypes, false, strmangle.SetComplement(llmDecisionRunPrimaryKeyColumns, llmDecisionRunColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*LLMDecisionRun{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddSnapshotLLMDecisionRuns(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.ID, first.SnapshotID) {
			t.Error("foreign key was wrong value", a.ID, first.SnapshotID)
		}
		if !queries.Equal(a.ID, second.SnapshotID) {
			t.Error("foreign key was wrong value", a.ID, second.SnapshotID)
		}

		if first.R.Snapshot != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Snapshot != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.SnapshotLLMDecisionRuns[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.SnapshotLLMDecisionRuns[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.SnapshotLLMDecisionRuns().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

